INSERT INTO evaluation_run (id, session_id, model_call_job_id, workflow_version)
SELECT #{id, jdbcType=OTHER},
       session.id,
       #{modelCallJobId, jdbcType=OTHER},
       #{workflowVersion, jdbcType=BIGINT}
FROM practice_session session
JOIN learning_task task ON task.id = session.task_id
JOIN model_call_job job ON job.id = #{modelCallJobId, jdbcType=OTHER}
WHERE session.id = #{sessionId, jdbcType=OTHER}
  AND session.status = 'COMPLETED'
  AND task.user_id = #{trustedUserId, jdbcType=OTHER}
  AND task.language_profile_id = #{languageProfileId, jdbcType=OTHER}
  AND job.user_id = #{trustedUserId, jdbcType=OTHER}
  AND job.language_profile_id = #{languageProfileId, jdbcType=OTHER}
  AND job.model_purpose = #{modelPurpose, jdbcType=VARCHAR}
  AND job.model_operation = #{modelOperation, jdbcType=VARCHAR}
  AND job.workflow_id = #{id, jdbcType=OTHER}
  AND job.workflow_step_id = #{workflowStepId, jdbcType=VARCHAR}
  AND job.workflow_version = #{workflowVersion, jdbcType=BIGINT}
RETURNING id, session_id, model_call_job_id, status, workflow_version, row_version,
          created_at, completed_at, failure_reason, grounding_rejection_reason

INSERT INTO validated_semantic_candidate (
    evaluation_run_id, session_id, material_id, material_published_version,
    rubric_reference, target_language, grounding_policy_version)
SELECT run.id, run.session_id,
       #{materialId, jdbcType=VARCHAR}, #{materialPublishedVersion, jdbcType=VARCHAR},
       #{rubricReference, jdbcType=VARCHAR}, #{targetLanguage, jdbcType=VARCHAR},
       #{groundingPolicyVersion, jdbcType=VARCHAR}

WHERE run.id = #{evaluationRunId, jdbcType=OTHER}
  AND run.session_id = #{sessionId, jdbcType=OTHER}
  AND run.status = 'PENDING'
  AND 
  AND task.material_id = #{materialId, jdbcType=VARCHAR}
  AND task.published_version = #{materialPublishedVersion, jdbcType=VARCHAR}
  AND profile.language_code = #{targetLanguage, jdbcType=VARCHAR}
  AND EXISTS (
      SELECT 1
      FROM model_call_job job
      WHERE job.id = run.model_call_job_id
        AND job.user_id = #{trustedUserId, jdbcType=OTHER}
        AND job.language_profile_id = #{languageProfileId, jdbcType=OTHER}
        AND job.model_purpose = 'EVALUATION'
        AND job.model_operation = 'TEXT_GENERATION'
        AND job.workflow_id = run.id
        AND job.workflow_step_id = 'SEMANTIC_EVALUATION'
        AND job.workflow_version = run.workflow_version
        AND job.execution_status = 'SUCCEEDED'
        AND job.consumption_status = 'CONSUMED'
  )
RETURNING evaluation_run_id, session_id, material_id, material_published_version,
          rubric_reference, target_language, grounding_policy_version, created_at

SELECT candidate.evaluation_run_id, candidate.session_id, candidate.material_id,
       candidate.material_published_version, candidate.rubric_reference,
       candidate.target_language, candidate.grounding_policy_version, candidate.created_at
FROM validated_semantic_candidate candidate
JOIN practice_session session ON session.id = candidate.session_id
JOIN learning_task task ON task.id = session.task_id
WHERE candidate.evaluation_run_id = #{evaluationRunId, jdbcType=OTHER}
  AND task.user_id = #{trustedUserId, jdbcType=OTHER}
  AND task.language_profile_id = #{languageProfileId, jdbcType=OTHER}
